#!/usr/bin/env node
/**
 * wag-messenger.js
 * Reads recent Facebook Messenger conversations using your existing Chrome
 * profile (already logged in — no password needed). Outputs JSON to stdout.
 *
 * Called by wag-server.py during Sync Messages.
 * Usage: node ~/Desktop/wag-messenger.js
 */

import { chromium } from 'playwright';
import path from 'path';
import os from 'os';

const DEBUG_PORT  = 9222;  // Chrome must be launched with --remote-debugging-port=9222
const DAYS_BACK   = 7;
const MAX_THREADS = 15;
const TIMEOUT     = 20000;

// ── Conversational classifier (mirrors wag-server.py logic) ──────────────────
const CONVO_PATTERNS = [
  /^(ok|okay|k|sure|yeah|yes|yep|nope|hmm|hm|lol|haha|nice|great|cool|thanks|thank you|ty|np|got it|sounds good|will do|on it|done|perfect|awesome|noted|for sure)$/i,
  /\bi'?m\b|\bi'?ll\b|\bi will\b|\bi just\b|\bima\b|\bi went\b|\bi got\b|\bi called\b/i,
];
const ACTION_PATTERNS = [
  /\?/,
  /\b(can you|could you|would you|please|send me|text me|call me|let me know)\b/i,
  /\b(appointment|appt|meeting|deadline|due|pay|owe|pick up|drop off)\b/i,
  /\$\d|\b\d{1,2}:\d{2}\b/,
  /\b(monday|tuesday|wednesday|thursday|friday|saturday|sunday)\b/i,
  /\b(tomorrow|tonight|this week|next week|today)\b/i,
];

function isConversational(text) {
  const t = text.trim().toLowerCase();
  if (CONVO_PATTERNS.some(p => p.test(t))) return true;
  if (ACTION_PATTERNS.some(p => p.test(t))) return false;
  return t.split(' ').length <= 10;
}

function todayISO() {
  return new Date().toISOString().slice(0, 10);
}

function taskId(sender, text) {
  // simple stable ID
  const raw = sender + text.slice(0, 40);
  let h = 0;
  for (let i = 0; i < raw.length; i++) {
    h = (Math.imul(31, h) + raw.charCodeAt(i)) | 0;
  }
  return 'msg_fb_' + Math.abs(h).toString(16).slice(0, 8);
}

// ── Main ──────────────────────────────────────────────────────────────────────
(async () => {
  // Connect to the already-running Chrome via remote debug port
  let browser;
  try {
    browser = await chromium.connectOverCDP(`http://localhost:${DEBUG_PORT}`);
  } catch (e) {
    process.stderr.write(`[messenger] Chrome not reachable on port ${DEBUG_PORT} — launch via the WAG app\n`);
    process.stdout.write(JSON.stringify({ tasks: [], error: 'chrome_not_connected', checked_at: new Date().toLocaleTimeString() }));
    process.exit(0);
  }

  const context = browser.contexts()[0] || await browser.newContext();
  const page = await context.newPage();
  const tasks = [];

  try {
    await page.goto('https://www.messenger.com', { waitUntil: 'domcontentloaded', timeout: TIMEOUT });

    // Check if logged in
    const url = page.url();
    if (url.includes('login') || url.includes('checkpoint')) {
      process.stderr.write('[messenger] Not logged in to Facebook\n');
      await context.close();
      process.stdout.write(JSON.stringify({ tasks: [], error: 'not_logged_in', checked_at: new Date().toLocaleTimeString() }));
      process.exit(0);
    }

    // Wait for conversation list
    await page.waitForSelector('[aria-label="Chats"]', { timeout: TIMEOUT }).catch(() => {});
    await page.waitForTimeout(2000);

    // Get conversation threads
    const threads = await page.evaluate((maxThreads) => {
      const results = [];

      // Try to find conversation list items
      const items = document.querySelectorAll('[data-testid="mwthreadlist-item"], a[href*="/t/"]');

      for (const item of Array.from(items).slice(0, maxThreads)) {
        try {
          // Get sender name
          const nameEl = item.querySelector('span[dir="auto"]') ||
                         item.querySelector('[data-testid="conversation_name"]');
          const name = nameEl ? nameEl.textContent.trim() : '';

          // Get snippet (last message preview)
          const snippets = item.querySelectorAll('span[dir="auto"]');
          let snippet = '';
          for (const s of snippets) {
            const t = s.textContent.trim();
            if (t && t !== name && t.length > 3) {
              snippet = t;
              break;
            }
          }

          // Get timestamp
          const timeEl = item.querySelector('abbr, time, [data-testid="conversation_timestamp"]');
          const timestamp = timeEl ? (timeEl.getAttribute('data-utime') || timeEl.textContent.trim()) : '';

          // Check if unread (bold text or unread indicator)
          const isUnread = item.querySelector('[data-testid="unread_count"]') !== null ||
                           item.classList.contains('_unread') ||
                           item.querySelector('span[style*="font-weight: 700"]') !== null ||
                           item.querySelector('span[style*="font-weight:700"]') !== null;

          // Get conversation URL/ID
          const link = item.closest('a') || item.querySelector('a');
          const href = link ? link.href : '';

          if (name && snippet) {
            results.push({ name, snippet, timestamp, isUnread, href });
          }
        } catch (_) {}
      }
      return results;
    }, MAX_THREADS);

    // Filter and convert to tasks
    const cutoff = new Date();
    cutoff.setDate(cutoff.getDate() - DAYS_BACK);

    for (const thread of threads) {
      const { name, snippet, isUnread } = thread;
      if (!snippet || !name) continue;

      // Skip if conversational
      if (isConversational(snippet)) continue;

      // Skip system/automated senders
      if (/marketplace|facebook|instagram|notification|alert/i.test(name)) continue;

      // Only include recent/unread unless clearly actionable
      const isActionable = ACTION_PATTERNS.some(p => p.test(snippet));
      if (!isUnread && !isActionable) continue;

      tasks.push({
        id:     taskId(name, snippet),
        date:   todayISO(),
        text:   `Reply to ${name} on Messenger: ${snippet.slice(0, 80)}`,
        urgent: isUnread && isActionable,
        source: 'messenger',
      });
    }

    process.stderr.write(`[messenger] ${threads.length} threads checked, ${tasks.length} tasks found\n`);

  } catch (err) {
    process.stderr.write('[messenger] Error: ' + err.message + '\n');
  } finally {
    await page.close();
    await browser.close();
  }

  const checked_at = new Date().toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
  process.stdout.write(JSON.stringify({ tasks, checked_at }));
})();
